 UnityEngine.InputSystem.InputSettings.BackgroundBehavior oldBackground;UnityEngine.InputSystem.Keyboard fixtureKeyboard;TerrierMatch m;string folder,saved;bool had,restored,drive,edgeNudge;Vector2 command;int errors;readonly StringBuilder report=new StringBuilder();void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",report.ToString());}void Log(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+s);Write();}}
 IEnumerator Fresh(){drive=false;m.SetupScreen();yield return null;m.setup.players[0].source=BowlingSource.Keyboard;for(int i=1;i<12;i++)m.setup.players[i].source=BowlingSource.AI;float readyUntil=Time.realtimeSinceStartup+2;while(!m.DevicesReady&&Time.realtimeSinceStartup<readyUntil)yield return null;bool started=m.StartMatch();m.ValidateSources(out var setupReason);Check(started,"fresh physical finish reproduction starts · ready="+m.DevicesReady+" reason="+setupReason+" key="+UnityEngine.InputSystem.Keyboard.current+" enabled="+UnityEngine.InputSystem.Keyboard.current?.enabled);if(!started)throw new InvalidOperationException("Finish fixture setup rejected: "+setupReason);float end=Time.realtimeSinceStartup+7;while(m.Phase!=TerrierPhase.Race&&Time.realtimeSinceStartup<end)yield return null;for(int i=1;i<12;i++)m.racers[i].Wreck();m.crowd.Stop();m.course.weather.Configure(1,1,0);m.finishDiagnostics.ResetTrace();m.finishDiagnostics.verbose=true;}
 void Place(float x,float yaw,float speed,float lateral=0){var t=m.racers[0].truck;t.body.maxLinearVelocity=650;t.body.position=m.course.World(new Vector3(x,.48f,m.course.Length-8));t.body.rotation=m.course.DrivingRotation*Quaternion.Euler(0,yaw,0);t.body.linearVelocity=m.course.Forward*speed+m.course.geometry.right*lateral;command=new Vector2(0,1);drive=true;}
