 yield return Fresh();Place(6,0,20);end=Time.realtimeSinceStartup+5;while(m.racers[0].Alive&&Time.realtimeSinceStartup<end)yield return null;Check(!m.racers[0].Alive&&!m.racers[0].Finished&&m.HeatWinner<0,"genuine pre-finish solid-wall slam still wrecks without bypass win");Check(m.wrecks!=null&&m.wrecks.Emissions==1&&m.wrecks.ActiveCount>=10,"wreck emits actual physical truck mesh pieces");report.AppendLine("TRACE WALL_SLAM\n"+m.finishDiagnostics.Report());drive=false;
 yield return Passage("high-speed swept passage cannot skip finish detection",0,0,550);m.racers[0].truck.body.maxLinearVelocity=36;report.AppendLine("ERRORS="+errors+". Controlled initial physics poses/velocities and software commands; no hardware/human playtest.");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("TERRIER_FINISH_PROBE_COMPLETE "+report);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void FixedUpdate(){if(drive&&m!=null&&m.Live&&m.Phase==TerrierPhase.Race){if(edgeNudge&&m.course.TruckBounds(m.racers[0].truck.shape).max.z>m.course.Length+.2f){edgeNudge=false;m.racers[0].truck.body.AddForce(m.course.geometry.right*1.8f,ForceMode.VelocityChange);}m.commands[0]=command;m.actions[0]=false;}}
